		case 'mg':
			return dose.value * multiplier;
		case 'mcg':
			return (dose.value * multiplier) / 1000;
		case 'g':
			return dose.value * multiplier * 1000;
		case 'mg/kg':
			if (weightKg === undefined) throw new UnitMismatchError('weight required for mg/kg dosing');
			return dose.value * weightKg * multiplier;
		case 'mg/kg/day':
