import type { MedicationConceptId, RxNormNode } from './types.js';

export type ResolvedConcept = { rxcui: MedicationConceptId; termType: RxNormNode['termType']; name: string; ingredients: MedicationConceptId[] };
export type UnmatchedConcept = { inputText: string; reason: 'not-found' | 'ambiguous'; blocksReconciliation: true };
export type ResolutionResult = { matched: ResolvedConcept } | { unmatched: UnmatchedConcept };

export class MedicationConceptResolver {
	constructor(private readonly graph: RxNormNode[]) {}

	resolve(input: string): ResolutionResult {
		const needle = input.trim().toLowerCase();
		const exact = this.graph.find((n) => (n.rxcui as unknown as string) === input.trim());
		const byName = exact ?? this.graph.find((n) => n.name.toLowerCase() === needle);
		if (byName) return { matched: this.toResolved(byName) };
		const partial = this.graph.filter((n) => n.name.toLowerCase().includes(needle));
		if (partial.length === 1) return { matched: this.toResolved(partial[0]!) };
		if (partial.length > 1) return { unmatched: { inputText: input, reason: 'ambiguous', blocksReconciliation: true } };
		return { unmatched: { inputText: input, reason: 'not-found', blocksReconciliation: true } };
	}

	getIngredients(rxcui: MedicationConceptId): MedicationConceptId[] {
		const node = this.graph.find((n) => n.rxcui === rxcui);
		if (!node) return [];
		if (node.termType === 'IN') return [node.rxcui];
		const direct = node.ingredients ?? [];
		if (direct.length > 0) return direct.flatMap((i) => this.getIngredients(i));
		return node.parentRxcuis.flatMap((p) => this.getIngredients(p));
	}

	private toResolved(node: RxNormNode): ResolvedConcept {
		return { rxcui: node.rxcui, termType: node.termType, name: node.name, ingredients: this.getIngredients(node.rxcui) };
	}
}

