import type { PatientId } from './types.js';

export type AuditEventType = 'reconciliation-decision' | 'alert-fired' | 'alert-suppressed' | 'task-created' | 'adherence-recorded';

export type AuditEvent = {
	id: string;
	type: AuditEventType;
	occurredAt: Date;
	patientId: PatientId;
	actorId: string;
	payload: Record<string, unknown>;
};

export class AuditLog {
	private readonly events: AuditEvent[] = [];
	private counter = 0;

	append(event: Omit<AuditEvent, 'id'>): AuditEvent {
		const stored: AuditEvent = { ...event, id: String(++this.counter) };
		this.events.push(stored);
		return stored;
	}

	getAll(): readonly AuditEvent[] {
		return [...this.events];
	}

	getByPatient(patientId: PatientId): readonly AuditEvent[] {
		return this.events.filter((e) => e.patientId === patientId);
	}
}

