		const log = new AuditLog();
		const a = log.append({ type: 'alert-fired', occurredAt: at, patientId: pidA, actorId: 'engine', payload: {} });
		const b = log.append({ type: 'task-created', occurredAt: at, patientId: pidB, actorId: 'engine', payload: {} });
		expect([a.id, b.id]).toEqual(['1', '2']);
		expect(log.getAll().map((e) => e.id)).toEqual(['1', '2']);
