export function evaluateRules(facts: PatientFacts, regimen: RegimenItem[], pack: ReferencePack): Alert[] {
	const active = regimen.filter((item) => item.status === 'active');
	return [
		...checkDuplicateIngredient(active, pack),
		...checkClassDuplication(active, pack),
		...checkMaxDailyDose(facts, active, pack),
		...checkAllergy(facts, active, pack),
		...checkContraindication(active, pack),
	];
}

