import type { Clock } from './clock.js';
import type { MedicationConceptResolver } from './medication-concept-resolver.js';
import type { DiscrepancyClass, MedicationConceptId } from './types.js';

export type MedicationSource = 'imported' | 'patient-reported' | 'clinician-approved';
export type ReconciliationItem = {
	conceptId: MedicationConceptId | null;
	inputText: string;
	source: MedicationSource;
	provenance: { importedAt: Date; importedBy: string };
};
export type Discrepancy = { item: ReconciliationItem; classification: DiscrepancyClass; reason?: string };
export type ReconciliationOutput = {
	accepted: ReconciliationItem[];
	rejected: ReconciliationItem[];
	unmatched: ReconciliationItem[];
	discrepancies: Discrepancy[];
};

export function reconcile(items: ReconciliationItem[], resolver: MedicationConceptResolver, clinicianApprovedIds: MedicationConceptId[], clock: Clock): ReconciliationOutput {
	void clock;
	const output: ReconciliationOutput = { accepted: [], rejected: [], unmatched: [], discrepancies: [] };
	const approved = new Set(clinicianApprovedIds.map(String));
	for (const item of items) {
		const resolution = resolver.resolve(item.inputText);
		if ('unmatched' in resolution) {
			output.unmatched.push({ ...item, conceptId: null });
			continue;
		}
		const resolved = { ...item, conceptId: resolution.matched.rxcui };
		if (approved.has(String(resolution.matched.rxcui))) {
			output.accepted.push(resolved);
			if (item.source === 'clinician-approved') {
				output.discrepancies.push({ item: resolved, classification: 'intentional-documented', reason: 'clinician-approved without import source' });
			}
		} else {
			output.rejected.push(resolved);
			output.discrepancies.push({ item: resolved, classification: 'unintentional', reason: 'present in ' + item.source + ' but absent from clinician-approved regimen' });
		}
	}
	return output;
}

