import type { Clock } from './clock.js';
import { dailyDoseMg, type FrequencyUnit, type Quantity } from './dose.js';
import type { MedicationConceptId } from './types.js';

export type RefillForecast = {
	conceptId: MedicationConceptId;
	lastFillDate: Date;
	remainingQuantityMg: number;
	dailyDoseMg: number | null;
	knownHoldDays: number;
	projectedExhaustionDate: Date | null;
	daysUntilExhaustion: number | null;
	isAtRisk: boolean;
};

const DAY_MS = 86400000;

export function forecastRefill(conceptId: MedicationConceptId, lastFillDate: Date, remainingQuantityMg: number, dose: Quantity, frequency: FrequencyUnit, knownHoldDays: number, clock: Clock, weightKg?: number): RefillForecast {
	const perDay = dailyDoseMg(dose, frequency, weightKg);
	if (perDay === null || perDay <= 0) {
		return { conceptId, lastFillDate, remainingQuantityMg, dailyDoseMg: perDay, knownHoldDays, projectedExhaustionDate: null, daysUntilExhaustion: null, isAtRisk: false };
	}
	const adjustedRemainingMg = remainingQuantityMg + knownHoldDays * perDay;
	const daysOfSupply = adjustedRemainingMg / perDay;
	const projectedExhaustionDate = new Date(lastFillDate.getTime() + daysOfSupply * DAY_MS);
	const daysUntilExhaustion = Math.floor((projectedExhaustionDate.getTime() - clock.now().getTime()) / DAY_MS);
	return { conceptId, lastFillDate, remainingQuantityMg, dailyDoseMg: perDay, knownHoldDays, projectedExhaustionDate, daysUntilExhaustion, isAtRisk: daysUntilExhaustion <= 7 };
}

