export const SUMMARY_DENYLIST: RegExp[] = [
	/\b\d+(\.\d+)?\s*(mg|mcg|g|score|risk|level)\b/i,
	/\b(diagnos|treat|prescri|administer)\w*\b/i,
];

export type PatientSummary = {
	patientId: PatientId;
	generatedAt: Date;
	activeCount: number;
	adherenceNote: string;
	refillReminders: string[];
	tasks: string[];
};

function assertAllowed(text: string): string {
	for (const pattern of SUMMARY_DENYLIST) {
		if (pattern.test(text)) throw new Error('summary contains prohibited content: ' + text);
	}
	return text;
}

export function generatePatientSummary(patientId: PatientId, regimen: RegimenItem[], adherence: AdherenceSummary, forecasts: RefillForecast[], openTasks: SafetyTask[], clock: Clock): PatientSummary {
	const adherenceNote = assertAllowed('You took ' + adherence.taken + ' of ' + adherence.total + ' scheduled doses in this period.');
	const refillReminders = forecasts.filter((f) => f.isAtRisk && f.daysUntilExhaustion !== null).map((f) => assertAllowed('One of your medicines may run low in about ' + f.daysUntilExhaustion + ' days. Please contact your pharmacy.'));
	const tasks = openTasks.filter((t) => t.type === 'caregiver-follow-up' || t.type === 'patient-education').map((t) => assertAllowed(t.description));
	return {
		patientId,
		generatedAt: clock.now(),
		activeCount: regimen.filter((r) => r.status === 'active').length,
		adherenceNote,
		refillReminders,
		tasks,
	};
}

