const adherence: AdherenceSummary = { patientId: pid, conceptId: cid, periodStart: new Date('2025-01-06T00:00:00Z'), periodEnd: new Date('2025-01-13T00:00:00Z'), taken: 4, missed: 6, skippedByInstruction: 0, heldByClinician: 0, unknown: 0, total: 10 };
const atRisk = forecastRefill(cid, new Date('2025-01-10T00:00:00Z'), 30, { value: 10, unit: 'mg' }, 'daily', 0, clock);
const clinicianTask: SafetyTask = { id: 'task-1', type: 'clinician-review', patientId: pid, createdAt: clock.now(), description: 'Escalate to prescriber.', traceToFacts: ['rx-apap-in'] };

describe('generatePatientSummary', () => {
	it('speaks in plain dose counts and day counts', () => {
		const summary = generatePatientSummary(pid, [], adherence, [atRisk], [], clock);
		expect(summary.adherenceNote).toContain('4 of 10');
		expect(summary.refillReminders[0]).toContain('days');
	});
	it('hides clinician-review tasks from patients', () => {
		const summary = generatePatientSummary(pid, [], adherence, [], [clinicianTask], clock);
		expect(summary.tasks).toHaveLength(0);
	});
	it('throws when a task description leaks a raw score', () => {
		const leaky: SafetyTask = { ...clinicianTask, type: 'patient-education', description: 'Your interaction risk score is 7.4' };
		expect(() => generatePatientSummary(pid, [], adherence, [], [leaky], clock)).toThrow(/prohibited/);
	});
});

import { describe, expect, it } from 'vitest';
import { FixedClock } from '../src/core/fixed-clock.js';
import { evaluateRules } from '../src/core/rule-engine.js';
import { MedicationConceptResolver } from '../src/core/medication-concept-resolver.js';
import { reconcile } from '../src/core/reconciliation.js';
import { SuppressionCeilingError, SuppressionStore } from '../src/core/suppression-store.js';
import { FIXTURE_REFERENCE_PACK } from '../src/fixtures/reference-pack.js';
import { FIXTURE_RXNORM_GRAPH } from '../src/fixtures/rxnorm-graph.js';
import { PATIENT_FIXTURES } from '../src/fixtures/patients.js';

const clock = new FixedClock(new Date('2025-01-15T08:00:00Z'));
const pack = FIXTURE_REFERENCE_PACK;

describe('flagship integration over the five seeded patients', () => {
	it('patient a: dup-ingredient fires only via MIN decomposition', () => {
		const alerts = evaluateRules(PATIENT_FIXTURES.a.facts, PATIENT_FIXTURES.a.regimen, pack);
		expect(alerts.some((a) => String(a.ruleId) === 'dup-ingredient')).toBe(true);
	});
	it('patient b: cephalexin moderate, aztreonam informational', () => {
		const alerts = evaluateRules(PATIENT_FIXTURES.b.facts, PATIENT_FIXTURES.b.regimen, pack);
		const severities = alerts.filter((a) => String(a.ruleId) === 'allergy').map((a) => a.severity).sort();
		expect(severities).toEqual(['informational', 'moderate']);
	});
	it('patient c: max-dose fires serious', () => {
		const alerts = evaluateRules(PATIENT_FIXTURES.c.facts, PATIENT_FIXTURES.c.regimen, pack);
		expect(alerts.some((a) => String(a.ruleId) === 'max-dose' && a.severity === 'serious')).toBe(true);
	});
	it('patient d: lb-derived weight evaluates without unit errors', () => {
		expect(() => evaluateRules(PATIENT_FIXTURES.d.facts, PATIENT_FIXTURES.d.regimen, pack)).not.toThrow();
	});
	it('patient e: suppression replay demotes but the ceiling holds', () => {
		const alerts = evaluateRules(PATIENT_FIXTURES.e.facts, PATIENT_FIXTURES.e.regimen, pack);
		const moderateOrSerious = alerts.find((a) => a.suppressible);
		const contraindicated = { ...alerts[0]!, severity: 'contraindicated' as const, suppressible: false };
		const store = new SuppressionStore();
		store.record(moderateOrSerious!, 'always-for-pair', 'dr-lee', 'known tolerated pair', undefined, clock);
		expect(store.isSuppressed(moderateOrSerious!, PATIENT_FIXTURES.e.facts.patientId, clock)).toBe(true);
		expect(() => store.record(contraindicated, 'always-for-pair', 'dr-lee', 'attempt', undefined, clock)).toThrow(SuppressionCeilingError);
	});
	it('evidence totality and free-text blocking hold everywhere', () => {
		for (const key of ['a', 'b', 'c', 'd', 'e'] as const) {
			const alerts = evaluateRules(PATIENT_FIXTURES[key].facts, PATIENT_FIXTURES[key].regimen, pack);
			expect(alerts.every((a) => a.evidence.length >= 1)).toBe(true);
		}
		const resolver = new MedicationConceptResolver(FIXTURE_RXNORM_GRAPH);
		const out = reconcile([{ conceptId: null, inputText: 'a water pill', source: 'patient-reported', provenance: { importedAt: new Date('2025-01-14T00:00:00Z'), importedBy: 'intake' } }], resolver, [], clock);
		expect(out.unmatched).toHaveLength(1);
	});
});
